/**
 * Helpers for shared-routine short links (https://getlimba.com/shared-routine/<code>,
 * older links /r/<code>).
 *
 * The routine lives in Supabase (`shared_routines`). The page reads it through
 * the backend's public endpoint (see sharedRoutineApi.ts), which also returns
 * stretch names, instructions and signed videos for the web player. These
 * helpers are pure so they can be unit tested and shared by the page, the
 * player and the analytics route.
 */

/** 7-character base62 code, as generated by `create_shared_routine`. */
const SHARE_CODE_RE = /^[0-9A-Za-z]{7}$/

export function isValidShareCode(code: unknown): code is string {
  return typeof code === 'string' && SHARE_CODE_RE.test(code)
}

/** Stretch fields the player uses, from the backend's StretchLibraryDto. */
export interface ApiStretch {
  id: string
  name: string | null
  reps: number | null
  target_muscles: string[] | null
  instructions: string | null
}

/** One item of GET /api/v1/public/shared-routines/{code}. */
export interface ApiSharedRoutineItem {
  /** Seconds per side. */
  d: number
  /** 1 when the stretch is done on each side. */
  x: 1 | null
  stretch: ApiStretch | null
  /** Signed video URL (about an hour), or null when there is no video. */
  video_url: string | null
  /** Epoch seconds when video_url stops working. */
  video_expires_at: number | null
}

/** Response of GET /api/v1/public/shared-routines/{code} (limba_backend). */
export interface ApiSharedRoutine {
  code: string
  /** Sender's first name, or null. */
  sender_name: string | null
  sender_id: string | null
  dropped_count: number
  stretches: ApiSharedRoutineItem[]
}

/** A stretch ready for the web player, mapped like the app's shared-routine screen. */
export interface PlayableStretch {
  id: string
  name: string
  /** Instructions split on '||', as the app shows them. */
  steps: string[]
  targetMuscles: string[]
  /** Seconds per side. */
  seconds: number
  bothSides: boolean
  /** Same rule as the app's exerciseMode: a library stretch with reps plays by reps. */
  mode: 'timed' | 'reps'
  reps: number | null
  videoUrl: string | null
  videoExpiresAt: number | null
}

/**
 * Maps the API items to playable stretches, dropping any with no stretch or a
 * bad duration (the app's sharedRoutineService drops the same ones).
 */
export function toPlayable(items: ApiSharedRoutineItem[] | null | undefined): PlayableStretch[] {
  if (!Array.isArray(items)) return []
  const playable: PlayableStretch[] = []
  for (const item of items) {
    const stretch = item?.stretch
    const seconds = Number(item?.d)
    if (!stretch?.id || !Number.isFinite(seconds) || seconds <= 0) continue
    const reps = Number(stretch.reps)
    playable.push({
      id: stretch.id,
      name: stretch.name?.trim() || 'Stretch',
      steps: (stretch.instructions ?? '')
        .split('||')
        .map((step) => step.trim())
        .filter(Boolean),
      targetMuscles: Array.isArray(stretch.target_muscles)
        ? stretch.target_muscles.filter((m): m is string => typeof m === 'string' && m.length > 0)
        : [],
      seconds: Math.round(seconds),
      bothSides: item.x === 1,
      mode: Number.isFinite(reps) && reps > 0 ? 'reps' : 'timed',
      reps: Number.isFinite(reps) && reps > 0 ? reps : null,
      videoUrl: typeof item.video_url === 'string' && item.video_url ? item.video_url : null,
      videoExpiresAt: typeof item.video_expires_at === 'number' ? item.video_expires_at : null,
    })
  }
  return playable
}

/** "lower_back" -> "Lower back". */
export function formatMuscle(muscle: string): string {
  const words = muscle.replace(/[_-]+/g, ' ').trim()
  return words ? words[0].toUpperCase() + words.slice(1).toLowerCase() : ''
}

export interface RoutineSummary {
  stretchCount: number
  totalSeconds: number
  /** Rounded up, so a 61-second routine reads as 2 min, never 0 min. */
  totalMinutes: number
}

export function summarise(stretches: PlayableStretch[]): RoutineSummary {
  const list = Array.isArray(stretches) ? stretches : []
  const totalSeconds = list.reduce((sum, stretch) => {
    const seconds = Number(stretch?.seconds)
    if (!Number.isFinite(seconds) || seconds <= 0) return sum
    return sum + seconds * (stretch.bothSides ? 2 : 1)
  }, 0)
  return {
    stretchCount: list.length,
    totalSeconds,
    totalMinutes: Math.ceil(totalSeconds / 60),
  }
}

/** "2:05" for 125 seconds, "45s" under a minute. */
export function formatDuration(totalSeconds: number): string {
  const s = Math.max(0, Math.round(totalSeconds))
  if (s < 60) return `${s}s`
  const minutes = Math.floor(s / 60)
  const rest = s % 60
  return rest === 0 ? `${minutes} min` : `${minutes}:${String(rest).padStart(2, '0')}`
}

/**
 * AppsFlyer OneLink that sends the visitor to the right store and, after install,
 * deep links into the shared routine (deferred deep link). Returns null when
 * NEXT_PUBLIC_ONELINK_URL isn't configured, so callers fall back to the plain
 * store links.
 */
export function buildOneLinkUrl(code: string): string | null {
  const base = process.env.NEXT_PUBLIC_ONELINK_URL
  if (!base) return null
  const params = new URLSearchParams({
    pid: 'routine_share',
    c: 'shared_routine',
    deep_link_value: code,
    deep_link_sub1: 'share',
  })
  return `${base}${base.includes('?') ? '&' : '?'}${params.toString()}`
}

/** Heading used by the page, the metadata and the OG tags. */
export function sharedRoutineTitle(name: string | null | undefined): string {
  const trimmed = typeof name === 'string' ? name.trim() : ''
  return trimmed
    ? `${trimmed} shared a routine with you`
    : 'A friend shared a routine with you'
}

export function sharedRoutineDescription(summary: RoutineSummary): string {
  const stretches = `${summary.stretchCount} ${summary.stretchCount === 1 ? 'stretch' : 'stretches'}`
  return `${stretches} · ${summary.totalMinutes} min. Free to try in Limba.`
}
